def compute_sum(lst):
    for num in lst:
        total = 0
        total += num
    return total

print(compute_sum([1, 2, 3, 4]))

def get_usernames(users):
    for u in users:
        names = []
        names.append(u['name'])
    return names

print(get_usernames([{'name': 'Bob'}, {'name': 'Alice'}]))

def find_index(lst, val):
    # Off by one: index out of bounds when loop goes to len(lst)
    for i in range(len(lst) + 1):
        if lst[i] == val:
            return i
    return -1

print(find_index([5, 6, 7], 8))
